import '../../domain/entities/competition.dart'; import '../../domain/repositories/competition_repository.dart'; import '../datasources/competition_remote_data_source.dart'; import '../dto/batch_delete_result.dart'; import '../dto/competition_mapper.dart'; class CompetitionRepositoryImpl implements CompetitionRepository { CompetitionRepositoryImpl(this._remote); final CompetitionRemoteDataSource _remote; @override Future<PagedCompetitionResult> list({int page=0,int size=20,CompetitionStatus? status,String? search}) async { final r=await _remote.list(page:page,size:size,status:status?.name.toUpperCase(),search:search); return PagedCompetitionResult(competitions:r.content.map(CompetitionMapper.fromDto).toList(growable:false),page:r.page,totalPages:r.totalPages,last:r.last); } @override Future<Competition> create({required String name,required String description}) async=>CompetitionMapper.fromDto(await _remote.create(name:name,description:description)); @override Future<Competition> update({required String id,required String name,required String description}) async=>CompetitionMapper.fromDto(await _remote.update(id:id,name:name,description:description)); @override Future<Competition> updateDefaults({required String id,required List<String> defaultDays,required List<String> defaultHours,required int defaultFieldCount}) async=>CompetitionMapper.fromDto(await _remote.updateDefaults(id:id,defaultDays:defaultDays,defaultHours:defaultHours,defaultFieldCount:defaultFieldCount)); @override Future<Competition> activate(String id) async=>CompetitionMapper.fromDto(await _remote.activate(id)); @override Future<Competition> close(String id) async=>CompetitionMapper.fromDto(await _remote.close(id)); @override Future<Competition> duplicate(String id,String newName) async=>CompetitionMapper.fromDto(await _remote.duplicate(id,newName)); @override Future<void> delete(String id)=>_remote.delete(id); @override Future<BatchDeleteResult> deleteMany(List<String> ids)=>_remote.deleteMany(ids); }
